def drop_field(where, fields, prefix):
    """Each field's store gone from a block of stores, the block being found by the text before it."""
    out = []
    block = "".join("    %s = 0;\n" % f for f in fields)
    for f in fields:
        out.append(("%s: %s" % (where, f), D, prefix + block, prefix + block.replace("    %s = 0;\n" % f, "")))
    return out


